# 方法一：n & (n-1) == 0（推薦）
class Solution:
    def isPowerOfTwo(self, n: int) -> bool:
        return n > 0 and (n & (n - 1)) == 0


# 方法二：n & (-n) == n
class Solution:
    def isPowerOfTwo(self, n: int) -> bool:
        return n > 0 and (n & -n) == n


# 方法三：數學法（不用迴圈/遞迴）
class Solution:
    def isPowerOfTwo(self, n: int) -> bool:
        return n > 0 and (1 << 30) % n == 0


# 方法四：迴圈除法（最直覺）
class Solution:
    def isPowerOfTwo(self, n: int) -> bool:
        if n <= 0:
            return False
        while n % 2 == 0:
            n //= 2
        return n == 1

