// 方法一：n & (n-1) == 0（推薦）
class Solution {
public:
    bool isPowerOfTwo(int n) {
        return n > 0 && (n & (n - 1)) == 0;
    }
};

// 方法二：n & (-n) == n
class Solution {
public:
    bool isPowerOfTwo(int n) {
        if (n <= 0) return false;
        // 用 long long 避免 INT_MIN 取負號溢位
        long long x = n;
        return (x & -x) == x;
    }
};

// 方法三：數學法（不用迴圈/遞迴）
class Solution {
public:
    bool isPowerOfTwo(int n) {
        return n > 0 && (1 << 30) % n == 0;
    }
};

